    { const r = await huyetPass(nv0, ev, cand, cur, curS, overl, () => kmAborted()); cur = r.cur; curS = r.curS; } // 7.12.4-thu.10: tìm có hệ thống cho huyệt ×2
    const e = ev(cur);
