  function hkLuu() { try { localStorage.setItem('vkx_hotkey', JSON.stringify(HK)); } catch (e) { /* bỏ qua */ } hkHint(); }
  const hkMa = (c) => String(c || '').replace(/^Key/, '').replace(/^Digit/, '').replace(/^Numpad/, 'Num ').replace(/^Arrow/, '');
  const hkTen = (h) => (h.ctrl ? 'Ctrl+' : '') + (h.alt ? 'Alt+' : '') + (h.shift ? 'Shift+' : '') + (hkMa(h.code) || '?');
  const hkKhop = (e) => HK.on && !!HK.code && e.code === HK.code && !!e.altKey === !!HK.alt && !!e.ctrlKey === !!HK.ctrl && !!e.shiftKey === !!HK.shift && !e.metaKey;
