            try { const nvB = clone(nv); nvB.kinhMach.manh = clone(ds[k].pieces); rs.push({ d: ds[k], x: kmSoBo(nvB, mode) }); }   // 8.3.2-thu.2: mỗi bộ chấm 2 mức (Hiện tại, Lĩnh Ngộ đầy)
