          const eTen = (E) => { const base = String(E.id).replace(/#.*$/, ''), d = c.enemies.get(base) || {}; return esc(d.ten || base) + (/#ta$/.test(E.id) ? ' (tinh anh)' : '') + (E.hi ? ' <span class="vk-mu">(trận cao)</span>' : ''); };
