        if (tong > BL_MAX - 200000) throw new Error('Tổng ' + (tong / 1048576).toFixed(1) + ' MB, quá ' + (BL_MAX / 1048576) + ' MB. Bỏ bớt ảnh hoặc bỏ Excel.');
        out.innerHTML = '<div class="vk-mu">Đang gửi…</div>';
