      seen.add(ac.id);
      const nd = run.nodes && run.nodes[slot], vars = nd && nd.encounter === ac.id ? nd.vars : null;
      const a = vars ? skPhanTich(def, vars) : X.byId.get(ac.id) || skPhanTich(def);
      c.enc = { id: ac.id, slot, vars: { ...(vars || {}) }, nodeFlags: {} }; c.noi = slot;
