      const g = G(), run = g.state && g.state.run, act = run && run.active;
      if (!act || act.done || !act.id) { skDlgGo(); return false; }
      if (SKC.soi.dlg === false) { skDlgGo(); return true; } // 7.17.4-thu.20: người dùng tắt hiện kết quả lựa chọn (true = khỏi thử lại)
      document.querySelectorAll('.vkx-sk-kq').forEach((e) => { if (e.dataset.enc !== act.id + '|' + (act.scene || '')) e.remove(); });
      if (!skCoreSan(() => {})) return false;
      const def = C().encounters.get(act.id); if (!def || def.kind === 'cua_hang') return false;
      const vars = act.vars || {}, a0 = skPhanTich(def, vars);
      const sc = act.scene && a0.scenes && a0.scenes[act.scene];
      const a = sc ? { ...a0, lc: sc.lc } : a0;
      const c = ctx(); c.enc = { id: act.id, slot: run.viTri, vars: { ...vars }, nodeFlags: {} }; c.noi = run.viTri;
      const tom = skNoiTom(a, c); if (!tom.length) return false;
