        for (let k = 0; k < 60 && first + k * ck <= o.N; k++) { const mo = first + k * ck, T = Math.max(x.y, mo); out.push({ x, mo, T, p, kip: T <= o.conTho, known: false, uoc: f.nam === null && k > 0 }); }
