    { const r0 = g.state.run; if (r0 && r0.thongBaoDai) auCall(() => g.closeLongNotice()); if (r0 && r0.thongBao && typeof g.dongThongBao === 'function') auCall(() => g.dongThongBao()); } // hộp “không sao tĩnh tâm” v.v. không để chặn bước sau
