    const run = g.state.run, nv = run.nhanVat;
    if (auLifeLeft() < (Number(cfg.tho) || 0)) return { stop: 'Thọ nguyên còn dưới ngưỡng giữ lại (' + cfg.tho + ' năm)' };
    const money = Math.floor(nv.linhThach || 0);
    if (cfg.ds.some((x) => x.giaMax !== 0) && money <= (Number(cfg.giuLt) || 0)) return { stop: 'Linh thạch (' + money + ') không còn trên mức giữ lại (' + cfg.giuLt + ')' };
    if (!st.house) return { stop: 'Chưa chọn được nhà đấu giá' };
    const h = st.house;
