    ds.addEventListener('click', (ev) => { const b = ev.target.closest && ev.target.closest('.dg-xoa'); if (!b) return; cfg.ds.splice(Number(b.dataset.i), 1); auSave(); ds.innerHTML = dgDsHtml(); });
