  const RR_PHAM = [['thien', 'Thiên'], ['bien_di', 'Biến Dị'], ['song', 'Song'], ['tap', 'Tạp'], ['vo', 'Vô'], ['ngu_hanh', 'Ngũ Hành']]; // dự phòng; danh sách thật dựng sống từ game ở rrPham()
