  function rrNgu() { try { const a = S.core && S.core.NGU_HANH; if (Array.isArray(a) && a.length) return a.map(String); } catch (e) { /* dự phòng */ } return ['kim', 'moc', 'thuy', 'hoa', 'tho']; }
