          const txt = nhan ? '×' + String(Math.round(v * 100) / 100).replace('.', ',') : (k === 'breakthrough' || k === 'craftSuccess' ? (v > 0 ? '+' : '') + Math.round(v * 100) + ' điểm %' : k === 'drugUsesPerRealm' ? v + ' viên' : (v > 0 ? '+' : '') + v);
          const tot = (v - b) * (I[k].tot || 1) > 0;
