  const rrTcTen = (id) => { try { const t = C().theChat.get(id); return t ? t.ten : String(id).replace(/^the_chat\./, ''); } catch (e) { return String(id); } };
  const rrXtTen = (id) => { try { const o = C().origins.get('origin.' + id) || C().origins.get(id); return o ? o.ten : String(id); } catch (e) { return String(id); } };
  // Thiên Mệnh: tính năng tùy chọn (cần K.datThienMenh). '' = Trời định. Ở Nghịch Thiên / Tuyệt Mệnh game bỏ Thiên Mệnh nên không áp.
  const rrTmBo = (dl) => { const K = S.core; return K && typeof K.isHardcoreOrWorse === 'function' ? !!K.isHardcoreOrWorse(dl) : (dl === 'hardcore' || dl === 'oneLife'); };
  const rrTmCo = () => !!(S.core && typeof S.core.datThienMenh === 'function');
