      const per = Math.max(1, o.perBuy || 1), money = Math.floor(g.state.run.nhanVat.linhThach || 0) - duTru;
      let q = Math.min(Math.ceil(thieu / per), Number.isFinite(o.stock) ? Math.floor(o.stock / per) : 999, o.maxQty > 0 ? o.maxQty : 999, 60), cost = 0;
