      return '<div style="font-size:13px;margin:2px 0">' + (i === 0 ? '<b>Sớm nhất</b>: ' : '') + 'năm ' + Math.floor(nam0 + t) + ' (' + (e.k ? 'bế quan ' + e.k + ' năm' : 'có sẵn') + (e.y >= 0.05 ? ', đi ' + dgThang(e.y) : '') + ') ở <b>' + esc(e.ten) + '</b>, ' + esc(placeName(c, e.slot)) + ': ' + esc(r.it.ten) + ' ~' + num(r.price, 0) + ' lt' + (r.price > vi ? ' <span class="vk-bad">(bạn có ' + num(vi, 0) + ', thiếu)</span>' : ' (bạn có ' + num(vi, 0) + ')') + '</div>';
