      out.push({ slot: n.slot, loai: 'hai', ten: 'Hái ' + ten(hp.herb), val, thoi, ghiChu: ten(hp.herb) + (hp.cliffHerb ? ' + ' + ten(hp.cliffHerb) + ' (vách)' : '') + (hp.age > 0 ? ' · ổ đã sống ' + hp.age + ' mùa' : '') + (ghi.length ? ' · ' + ghi.join('; ') : '') + mua });
