    let h = `<div style="margin:8px 0"><b>Ghé ${R.steps.length} nơi trong ${num(R.total)} / ${num(R.N)} năm</b>${R.quay ? ' <span class="vk-mu">(gồm đường quay về)</span>' : ''} <span class="vk-mu">· ${R.nJobs} việc được xét</span></div>`;
